    TwistExpander_Saiph_Arx::KEY_B_D_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(SAIPH_KEY_B_D_IceLaneA, SAIPH_KEY_B_D_IceLaneB, SAIPH_KEY_B_D_IceLaneC, SAIPH_KEY_B_D_IceLaneD, &(pWorkSpace->mKeyBoxB[3U][0]));

