    TwistExpander_Saiph_Arx::KEY_B_E_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(SAIPH_KEY_B_E_IceLaneA, SAIPH_KEY_B_E_IceLaneB, SAIPH_KEY_B_E_IceLaneC, SAIPH_KEY_B_E_IceLaneD, &(pWorkSpace->mKeyBoxB[4U][0]));

    // Key flow — B / F

